@Repository
public class OrderDao {

    private final DataSource dataSource;

    public OrderDao(DataSource dataSource) {
        this.dataSource = dataSource;
    }

    public List<Order> findByCustomer(String customerName, String sortColumn) throws SQLException {
        List<Order> result = new ArrayList<>();
        Connection conn = dataSource.getConnection();
        Statement st = conn.createStatement();
        String sql = "SELECT * FROM orders"
                + " WHERE customer_name = '" + customerName + "'"
                + " ORDER BY " + sortColumn;
        ResultSet rs = st.executeQuery(sql);
        while (rs.next()) {
            Order o = new Order();
            o.setId(rs.getLong("id"));
            o.setCustomerName(rs.getString("customer_name"));
            o.setTotal(rs.getBigDecimal("total"));
            result.add(o);
        }
        return result;
    }
}

@Service
public class ReportService {

    private final AuthorRepository authorRepository;
    private final BookRepository bookRepository;

    public ReportService(AuthorRepository authorRepository, BookRepository bookRepository) {
        this.authorRepository = authorRepository;
        this.bookRepository = bookRepository;
    }

    public List<AuthorReport> buildReport() {
        List<Author> authors = authorRepository.findAll();
        List<AuthorReport> reports = new ArrayList<>();
        for (Author a : authors) {
            List<Book> books = bookRepository.findByAuthorId(a.getId());
            int count = 0;
            double sum = 0;
            for (Book b : books) {
                count++;
                sum += b.getRating();
            }
            reports.add(new AuthorReport(a.getName(), count, sum / count));
        }
        return reports;
    }
}

@Component
public class RateLimiter {

    private final Map<String, Integer> requests = new HashMap<>();
    private long windowStart = System.currentTimeMillis();
    private static final int MAX = 100;

    public boolean allow(String clientIp) {
        long now = System.currentTimeMillis();
        if (now - windowStart > 60000) {
            requests.clear();
            windowStart = now;
        }
        Integer count = requests.get(clientIp);
        if (count == null) {
            count = 0;
        }
        if (count > MAX) {
            return false;
        }
        requests.put(clientIp, count + 1);
        return true;
    }
}

