@RestController
@RequestMapping("/api/accounts")
public class TransferController {

    private final AccountRepository accountRepository;

    public TransferController(AccountRepository accountRepository) {
        this.accountRepository = accountRepository;
    }

    @PostMapping("/transfer")
    public Account transfer(@RequestParam Long fromId, @RequestParam Long toId,
                            @RequestParam BigDecimal amount) {
        Account from = accountRepository.findById(fromId).get();
        Account to = accountRepository.findById(toId).get();
        if (from.getBalance().compareTo(amount) < 0) {
            throw new IllegalStateException("Saldo insufficiente");
        }
        from.setBalance(from.getBalance().subtract(amount));
        accountRepository.save(from);
        to.setBalance(to.getBalance().add(amount));
        accountRepository.save(to);
        return from;
    }
}

public class EventService {

    private static final SimpleDateFormat FORMAT = new SimpleDateFormat("dd/MM/yyyy");
    private static List<Event> cache = new ArrayList<>();

    public static List<Event> getCache() {
        return cache;
    }

    public String describe(Event e) {
        return e.getTitle() + " - " + FORMAT.format(e.getDate());
    }

    public List<Event> upcoming(List<Event> events) {
        List<Event> result = new ArrayList<>();
        for (Event e : events) {
            if (e.getDate().after(new Date())) {
                if (!result.contains(e)) {
                    result.add(e);
                }
            }
        }
        cache = result;
        return result;
    }

    public void removePast(List<Event> events) {
        for (Event e : events) {
            if (e.getDate().before(new Date())) {
                events.remove(e);
            }
        }
    }
}

@Service
public class OrderService {

    private final OrderRepository orderRepository;
    private final PaymentClient paymentClient;
    private final Logger log = LoggerFactory.getLogger(OrderService.class);

    public OrderService(OrderRepository orderRepository, PaymentClient paymentClient) {
        this.orderRepository = orderRepository;
        this.paymentClient = paymentClient;
    }

    public void processAll(List<Long> orderIds) {
        for (Long id : orderIds) {
            processOne(id);
        }
    }

    @Transactional
    public void processOne(Long id) {
        Order order = orderRepository.findById(id).orElseThrow();
        if (order.getStatus().equals("PAID")) {
            return;
        }
        try {
            paymentClient.charge(order.getCustomerId(), order.getTotal());
            order.setStatus("PAID");
        } catch (Exception e) {
            log.error("Pagamento fallito");
        }
        orderRepository.save(order);
    }
}

