def find_duplicates(emails):
    duplicates = []
    for i in range(len(emails)):
        for j in range(len(emails)):
            if i != j and emails[i] == emails[j]:
                if emails[i] not in duplicates:
                    duplicates.append(emails[i])
    return duplicates


def merge_customers(old, new):
    result = old
    for c in new:
        found = False
        for o in result:
            if o["id"] == c["id"]:
                o.update(c)
                found = True
        if not found:
            result.append(c)
