def unique_points(points):
    seen = set()
    for p in points:
        seen.add(p)
    return list(seen)


def parse_points(rows):
    points = []
    for row in rows:
        try:
            x, y = row.split(";")
            points.append(Point(float(x), float(y)))
        except Exception:
            pass
    return points

